// === go-eCharger MQTT -> Loxone UDP (minimal) ===
// Sendet NUR die vier Werte, die der Wb2-Baustein braucht:
//   Vc       = Vehicle Connected (0/1) aus go-e 'car'
//   P_total  = aktuelle Gesamt-Leistung in W (selbst aus V x A gerechnet)
//   Wh_total = Gesamt-Energie in Wh aus go-e 'eto' (0.1 kWh x 100)
//   Cac      = Cable max Ampere aus go-e 'cbl'
// Bei Wertaenderung sofort; bei gleichen Werten alle 60 s ein Heartbeat.

const HEARTBEAT_MS = 60000;

let cache  = flow.get('goeCache')  || {};
let lastHb = flow.get('goeLastHb') || 0;

const topic = msg.topic || '';
const parts = topic.split('/');
if (parts.length < 3) return null;
const key = parts[parts.length - 1];
const raw = msg.payload;

const changed = [];
function setVal(name, val) {
    if (cache[name] === val) return;
    cache[name] = val;
    changed.push(name);
}

switch (key) {
    case 'car':
        // 1=frei, 2=laedt, 3=wartet, 4=fertig, 5=error
        // Vc = 1 sobald ein Auto angesteckt ist
        setVal('Vc', Number(raw) >= 2 && Number(raw) <= 4 ? 1 : 0);
        break;

    case 'eto':
        // Total energy in 0.1 kWh -> x100 = Wh
        setVal('Wh_total', Math.round((Number(raw) || 0) * 100));
        break;

    case 'cbl':
        setVal('Cac', Number(raw) || 0);
        break;

    case 'nrg': {
        let nrg = raw;
        if (typeof raw === 'string') {
            try { nrg = JSON.parse(raw); } catch (e) { return null; }
        }
        if (!Array.isArray(nrg) || nrg.length < 7) return null;

        // P_total robust aus V x A gerechnet
        const v1 = Number(nrg[0]) || 0;
        const v2 = Number(nrg[1]) || 0;
        const v3 = Number(nrg[2]) || 0;
        const a1 = Number(nrg[4]) || 0;
        const a2 = Number(nrg[5]) || 0;
        const a3 = Number(nrg[6]) || 0;
        setVal('P_total', Math.round(v1 * a1 + v2 * a2 + v3 * a3));
        break;
    }

    default:
        return null;
}

flow.set('goeCache', cache);

const now = Date.now();
const out = [];

if (now - lastHb > HEARTBEAT_MS) {
    flow.set('goeLastHb', now);
    for (const [k, v] of Object.entries(cache)) {
        out.push({ payload: `goe-e/${k}/${v}` });
    }
    node.status({ fill: 'blue', shape: 'dot',
                  text: `heartbeat ${out.length} keys @ ${new Date().toLocaleTimeString()}` });
} else if (changed.length > 0) {
    for (const k of changed) {
        out.push({ payload: `goe-e/${k}/${cache[k]}` });
    }
    node.status({ fill: 'green', shape: 'dot',
                  text: `${changed.join(',')} @ ${new Date().toLocaleTimeString()}` });
}

for (const m of out) node.send(m);
return null;

// === Loxone UDP -> go-eCharger MQTT ===
// Akzeptiert KEY=WERT oder KEY/WERT.
// CA     = Charging Allowed (0/1)  -> MQTT frc (1=stop, 2=force on)
// TP     = Target Power kW         -> MQTT psm (1=1-ph, 2=3-ph) + amp (6..16 A)
// PHASEN = 1 oder 3                -> MQTT psm direkt
// STROM  = Ampere                  -> MQTT amp direkt

const SERIAL  = '413226';   // <-- ggf. anpassen
const U_PHASE = 230;        // Phasenspannung

const raw = String(msg.payload || '').trim();
const m = raw.match(/^(\w+)\s*[=\/]\s*(-?\d+(?:\.\d+)?)$/);
if (!m) {
    node.status({ fill: 'red', shape: 'ring', text: 'Parse-Fehler: ' + raw });
    return null;
}
const key = m[1].toUpperCase();
const val = Number(m[2]);

const out = [];

switch (key) {
    case 'CA':
        out.push({ topic: `go-eCharger/${SERIAL}/frc/set`, payload: val ? 2 : 1 });
        break;

    case 'TP': {
        let psm, amp;
        if (val <= 3.7) {
            psm = 1;
            amp = Math.max(6, Math.min(16, Math.round(val * 1000 / U_PHASE)));
        } else {
            psm = 2;
            amp = Math.max(6, Math.min(16, Math.round(val * 1000 / (U_PHASE * 3))));
        }
        out.push({ topic: `go-eCharger/${SERIAL}/psm/set`, payload: psm });
        out.push({ topic: `go-eCharger/${SERIAL}/amp/set`, payload: amp });
        break;
    }

    case 'PHASEN':
        out.push({ topic: `go-eCharger/${SERIAL}/psm/set`, payload: val === 3 ? 2 : 1 });
        break;

    case 'STROM':
        out.push({ topic: `go-eCharger/${SERIAL}/amp/set`,
                   payload: Math.max(6, Math.min(16, Math.round(val))) });
        break;

    default:
        node.status({ fill: 'yellow', shape: 'ring', text: `unbekannt: ${key}=${val}` });
        return null;
}

node.status({ fill: 'green', shape: 'dot',
              text: `${key}=${val} -> ${out.length} MQTT @ ${new Date().toLocaleTimeString()}` });

for (const o of out) node.send(o);
return null;
